CREATE TABLE Employee (
    Employee_ID INT PRIMARY KEY,
    Employee_Name NVARCHAR(100) NULL,
    Email NVARCHAR(100) NULL,
    Sex NVARCHAR(20) NULL,
    Salary FLOAT NULL,
    ContactNo INT NULL,
    Role NVARCHAR(50) NULL
);


CREATE TABLE Patient (
    Patient_ID INT PRIMARY KEY,
    Patient_Name NVARCHAR(100) NULL,
    Gender NVARCHAR(20) NULL,
    Phone_Number NVARCHAR(20) NULL,
    Email NVARCHAR(100) NULL
);


CREATE TABLE Room (
    Room_ID INT PRIMARY KEY,
    Room_Type NVARCHAR(50) NOT NULL,
    Location NVARCHAR(100) NOT NULL,
    No_Of_Beds INT NOT NULL,
    No_Of_Chairs INT NOT NULL,
    Ward_Charge FLOAT NOT NULL
);


CREATE TABLE MedicineCatg (
    Med_Catg_Code INT PRIMARY KEY,
    BrandName NVARCHAR(100) NOT NULL,
    CompanyName NVARCHAR(100) NOT NULL,
    ModifiedDate DATETIME NOT NULL
);


CREATE TABLE MedicineSubCatg (
    Med_Sub_Ref_No INT PRIMARY KEY,
    Med_Catg_Code INT NOT NULL,
    Name NVARCHAR(100) NOT NULL,
    ManufactDate DATETIME NOT NULL,
    ExpiryDate DATETIME NOT NULL,
    ModifiedDate DATETIME NOT NULL,

    CONSTRAINT FK_MedicineSubCatg_MedicineCatg
        FOREIGN KEY (Med_Catg_Code)
        REFERENCES MedicineCatg(Med_Catg_Code)
);


CREATE TABLE PatientAddress (
    Patient_ID INT PRIMARY KEY,
    Address NVARCHAR(200) NOT NULL,
    City NVARCHAR(100) NOT NULL,
    Country NVARCHAR(100) NOT NULL,

    CONSTRAINT FK_PatientAddress_Patient
        FOREIGN KEY (Patient_ID)
        REFERENCES Patient(Patient_ID)
);


CREATE TABLE Record (
    Record_ID INT PRIMARY KEY,
    Patient_ID INT NOT NULL,
    Employee_ID INT NOT NULL,
    Age INT NOT NULL,
    Room_ID INT NOT NULL,
    Treatment_Start_Date DATETIME NOT NULL,
    Treatment_End_Date DATETIME NOT NULL,
    Response NVARCHAR(500) NOT NULL,
    Description NVARCHAR(1000) NOT NULL,

    CONSTRAINT FK_Record_Patient
        FOREIGN KEY (Patient_ID)
        REFERENCES Patient(Patient_ID),

    CONSTRAINT FK_Record_Employee
        FOREIGN KEY (Employee_ID)
        REFERENCES Employee(Employee_ID),

    CONSTRAINT FK_Record_Room
        FOREIGN KEY (Room_ID)
        REFERENCES Room(Room_ID)
);


CREATE TABLE Medication (
    Med_Code INT PRIMARY KEY,
    Med_Sub_Ref_No INT NOT NULL,
    Med_Name NVARCHAR(100) NOT NULL,
    Quantity INT NOT NULL,
    Price FLOAT NOT NULL,
    Patient_ID INT NOT NULL,

    CONSTRAINT FK_Medication_MedicineSubCatg
        FOREIGN KEY (Med_Sub_Ref_No)
        REFERENCES MedicineSubCatg(Med_Sub_Ref_No),

    CONSTRAINT FK_Medication_Patient
        FOREIGN KEY (Patient_ID)
        REFERENCES Patient(Patient_ID)
);

CREATE TABLE PatientMedication (
    Patient_ID INT NOT NULL,
    Med_Code INT NOT NULL,

    PRIMARY KEY (Patient_ID, Med_Code),

    FOREIGN KEY (Patient_ID)
        REFERENCES Patient(Patient_ID),

    FOREIGN KEY (Med_Code)
        REFERENCES Medication(Med_Code)
);


