-- 8. Record
SELECT s.value AS Missing_Patient_ID
FROM GENERATE_SERIES(1, 1000) AS s
LEFT JOIN HospitalDB.dbo.Patient AS p 
    ON s.value = p.Patient_ID
WHERE p.Patient_ID IS NULL
ORDER BY Missing_Patient_ID;

